import re
import unicodedata


def title_case(s):
    return s.title()


def slugify(s):
    s = unicodedata.normalize("NFKD", s)
    s = s.encode("ascii", "ignore").decode("ascii")
    s = re.sub(r"[^a-zA-Z0-9]+", "-", s)
    return s.strip("-").lower()
EOF
